package app.kinnect.audit;
import android.app.*;import android.os.*;import android.content.*;import android.view.*;import android.widget.*;import android.graphics.*;import java.lang.reflect.*;import java.io.*;import org.json.*;
public class AboutAudit extends Instrumentation {
 private static void field(Activity a,String n,Object v)throws Exception{Field f=a.getClass().getDeclaredField(n);f.setAccessible(true);f.set(a,v);}
 private static String text(View v){String s=v instanceof TextView?((TextView)v).getText().toString()+"\n":"";if(v instanceof android.view.ViewGroup){android.view.ViewGroup g=(android.view.ViewGroup)v;for(int i=0;i<g.getChildCount();i++)s+=text(g.getChildAt(i));}return s;}
 public void onCreate(Bundle b){super.onCreate(b);start();}
 public void onStart(){Bundle result=new Bundle();try{
  Activity a=startActivitySync(new Intent().setClassName("app.kinnect.live","app.kinnect.live.MainActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Thread.sleep(1300);final LinearLayout[] root=new LinearLayout[1];
  runOnMainSync(()->{try{JSONObject user=new JSONObject().put("id","about-local").put("name","Kiểm tra hồ sơ").put("bio","Mình thích những cuộc trò chuyện chân thành.").put("city","CITY_SECRET").put("height",175).put("weight",68).put("occupation","Thiết kế và sáng tạo").put("school","SCHOOL_SECRET").put("identityPublic",false).put("gender","IDENTITY_SECRET").put("joinedAt",1760000000000L).put("interests",new JSONArray().put("Âm nhạc").put("Du lịch").put("Nhiếp ảnh")).put("profileVisibility",new JSONObject().put("city",false).put("school",false));field(a,"me",user);ScrollView scroll=new ScrollView(a);root[0]=new LinearLayout(a);root[0].setOrientation(1);root[0].setPadding(24,24,24,24);scroll.addView(root[0]);a.setContentView(scroll);field(a,"content",root[0]);Method m=a.getClass().getDeclaredMethod("profileSections",JSONObject.class);m.setAccessible(true);m.invoke(a,user);HorizontalScrollView tabs=(HorizontalScrollView)root[0].getChildAt(0);LinearLayout controls=(LinearLayout)tabs.getChildAt(0);String[] labels={"Giới thiệu","Bài viết","Album ảnh","Video"};for(int i=0;i<4;i++)if(!((TextView)controls.getChildAt(i)).getText().toString().equals(labels[i]))throw new AssertionError("Tab order differs");controls.getChildAt(0).performClick();String shown=text(root[0]);for(String value:new String[]{"Giới thiệu","175 cm","68 kg","Thiết kế và sáng tạo","Âm nhạc","Chỉnh sửa hồ sơ"})if(!shown.contains(value))throw new AssertionError("Missing "+value);for(String value:new String[]{"CITY_SECRET","SCHOOL_SECRET","IDENTITY_SECRET"})if(shown.contains(value))throw new AssertionError("Hidden field exposed");}catch(Exception e){throw new RuntimeException(e);}});waitForIdleSync();Thread.sleep(200);File screenshot=new File(a.getExternalFilesDir(null),"profile-about.png");try(FileOutputStream out=new FileOutputStream(screenshot)){getUiAutomation().takeScreenshot().compress(Bitmap.CompressFormat.PNG,100,out);}result.putString("result","PASS: actual APK four-tab order, public information, units and privacy filtering");finish(Activity.RESULT_OK,result);
 }catch(Throwable t){result.putString("error",t.toString());finish(Activity.RESULT_CANCELED,result);}}
}
